// Module 4 — Web Basics & HTML
// Bloom's-aligned MCQs. Each topic follows the progression:
// Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze · Q9 Evaluate · Q10 Create
// All distractors are Grade A: every option is plausible and of similar length
// (or longer than the correct answer) to prevent length-based guessing.
// No literal HTML code in the option strings — code samples live in `why`.

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: WWW, URL, HTTP, Server, Browser ───
  1: [
    { q: "Which statement correctly distinguishes the Internet from the World Wide Web?", opts: ["They are two different names for exactly the same worldwide network of computers", "The Internet is the global network of computers; the Web is one service (pages over HTTP) running on it", "The Web was invented before the Internet and eventually grew the network around itself and most modern teams have moved to exactly this way of doing things", "Only the Web uses IP addresses; the rest of the Internet works without them"], ans: 1, why: "The Internet is the global network of connected computers. The Web is ONE application on top of it — HTML pages fetched over HTTP. Email, video calls, and online games also use the Internet without being \"the Web.\" Internet is the road; the Web is one kind of vehicle that drives on it.", bloom: "remember" },
    { q: "What is the main job of a web browser when you open a page?", opts: ["To store every website in the world on your device so it opens instantly offline", "To scan the page for viruses before any part of it is allowed to load", "To translate your typing into the language spoken at the server's country", "To ask a server for the page, then read the HTML and draw it on the screen"], ans: 3, why: "A browser sends a request to the server, receives HTML (plus CSS, JS, images), then renders that code into the visual page you see. Browsers also run JavaScript and handle user input. Think of the browser as a \"reader and painter\" for web pages.", bloom: "remember" },
    { q: "Why does HTTPS matter more than plain HTTP for a login page where you type your password?", opts: ["HTTPS just loads faster than HTTP, especially on busy university networks", "HTTPS uses a nicer colour scheme in the address bar so users feel more confident", "HTTPS encrypts the data travelling between you and the server, while HTTP sends it as readable text", "HTTP was officially removed from the Internet last year and only old browsers still support it and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "Plain HTTP sends your password as readable text across every network it passes through. HTTPS scrambles it, so anyone intercepting the traffic just sees gibberish. On public Wi-Fi especially, plain HTTP means anyone nearby can read your form submissions.", bloom: "understand" },
    { q: "A URL like https://shop.example.com/cart?id=42 has several parts. What does the \"shop.example.com\" part represent?", opts: ["The exact file name of the HTML page being requested from the server's disk", "The domain name — a human-friendly label that DNS will turn into an IP address", "The query string that tells the server which product the user wants to buy", "The protocol that decides whether to use encryption or plain text for the trip"], ans: 1, why: "That piece is the domain name. DNS looks it up and returns the server's IP address. The protocol is the https://, the path is /cart, and ?id=42 is the query string. Each part has its own role.", bloom: "understand" },
    { q: "You type library.uni.edu into a browser and the page appears. Put these in order: (A) DNS returns the IP, (B) browser renders the HTML, (C) browser asks DNS for the IP, (D) server sends HTML back.", opts: ["A first, then B, then C, then D — the browser draws before it even asks", "B first, then D, then A, then C — rendering happens before any lookup", "C first, then A, then D, then B — ask, get IP, fetch page, draw it", "D first, then C, then A, then B — the server pushes before being asked"], ans: 2, why: "Applying the request lifecycle: ask DNS (C) → get IP back (A) → fetch the page (D) → render it (B). Browsers can't fetch without an IP, and they can't render without HTML. The order is a natural chain.", bloom: "apply" },
    { q: "A friend types google.com and nothing loads, though WhatsApp and YouTube work fine on the same phone. What's the most likely single thing to check first?", opts: ["Whether the keyboard is physically broken and sending wrong letters to the browser bar", "Whether deleting and reinstalling the browser would fix every possible network problem", "Whether the CPU is overheating and silently refusing to run browser code today", "DNS resolution — try a direct IP like 8.8.8.8 to confirm the internet itself is fine"], ans: 3, why: "If other apps work, the internet itself is reachable, but domain names aren't resolving. Try a direct IP: if that works, DNS is the culprit. Swapping to 1.1.1.1 or 8.8.8.8 often fixes it. Isolate the failing layer instead of guessing.", bloom: "apply" },
    { q: "A cafe Wi-Fi blocks a student's favourite site. Applying what you know about the request chain, where is the block most likely happening?", opts: ["Inside the browser itself — every browser ships with a list of sites it refuses to show", "At the DNS server the Wi-Fi forces you to use, returning \"not found\" for that domain", "In the HTML of the blocked page, which contains a line that hides itself from students", "On the student's phone screen, where the pixels have been disabled for that website"], ans: 1, why: "Cafe and school networks commonly filter by pointing DNS lookups at a controlled server that either returns nothing or a \"blocked\" page. The site itself is fine; the local DNS step is the gate. That's why changing DNS sometimes bypasses weak filters.", bloom: "apply" },
    { q: "A page shows \"Not secure\" even though the URL starts with https://. What does this usually mean?", opts: ["The HTTPS itself is totally broken and no bank in the world can use it safely anymore", "The browser has a bug and should be reinstalled before visiting the site one more time", "HTTPS is active but there's a certificate problem: expired, wrong domain, self-signed, or mixed content", "The site is perfectly safe because the \"s\" in HTTPS is already visible in the address bar and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "HTTPS is on, but the certificate — which proves identity — has an issue: expired, issued to a different domain, self-signed, or the page loads some HTTP resources alongside HTTPS. Encryption may work, but \"who are you really talking to?\" failed. Treat it as a warning, not a decoration.", bloom: "analyze" },
    { q: "Evaluate this claim: \"URLs are outdated because everyone uses apps now instead of browsers.\"", opts: ["Correct — URLs are slowly dying out and will be gone from normal internet use within the decade", "This question doesn't matter because neither URLs nor apps really exist on modern phones anyway", "Correct — apps have completely replaced URLs with secret numeric codes only the app can read", "Flawed — apps still use URLs under the hood for API calls, deep links, and sharing content"], ans: 3, why: "Apps still make HTTP requests to URL endpoints under the hood. Deep links like myapp://section/item/123 use URL structure. Anywhere a resource has an addressable location, the URL idea lives on — apps just hide it from your eyes.", bloom: "evaluate" },
    { q: "Design a simple 5-step explanation of \"what happens when I visit a website\" that a 10-year-old could follow without jargon.", opts: ["You type the URL, ask a \"phonebook\" (DNS), send a \"letter\" (HTTP), the server replies, your phone draws it", "Your phone has secretly stored every website in the world ahead of time and simply opens the local copy and most modern teams have moved to exactly this way of doing things", "Begin with a detailed explanation of the TCP three-way handshake, then TLS, then HTTP/2 multiplexing", "The internet sends you the full finished page directly — no steps, no lookups, no rendering involved"], ans: 0, why: "Good explanation: 1) Type a name (URL). 2) Phone asks a \"phonebook\" (DNS) for the number (IP). 3) Phone sends a \"letter\" (HTTP request). 4) The far computer (server) sends the page back. 5) Your phone draws it. Five friendly steps cover the full loop without jargon.", bloom: "create" },
  ],

  // ─── Topic 2: HTML Skeleton (DOCTYPE, html, head, body) ───
  2: [
    { q: "Which line correctly opens a modern HTML5 document?", opts: ["A tag written like HTML5 in capital angle brackets, with no slash or exclamation mark", "An html tag with a version attribute that says \"5\" inside double quotes as its value", "A doctype declaration written with both an exclamation mark and the word HTML5 together", "The short HTML5 doctype: an exclamation mark, the word DOCTYPE, and the word html"], ans: 3, why: "HTML5's DOCTYPE is literally <!DOCTYPE html> — no version number, no extra attributes. Anything else either triggers quirks mode or is made up. Short, standard, required as the first line.", bloom: "remember" },
    { q: "Inside the HTML skeleton, which element holds the stuff that actually appears on the screen?", opts: ["The head element, because that is where all the main writing lives by default", "The doctype line, because it tells the browser which pixels to draw on the page", "The html element by itself, which shows everything inside it without needing a body and most modern teams have moved to exactly this way of doing things", "The body element, because that is where the visible content like text and images goes"], ans: 3, why: "<body> holds the content that renders on the page — text, images, lists, everything visible. <head> holds metadata (title, charset, links) that configures the page but doesn't display. Two rooms: setup room, showing room.", bloom: "remember" },
    { q: "Why is content inside <head> NOT drawn on the page, while content inside <body> IS?", opts: ["It's an old historical accident that browser vendors chose at random a long time ago", "<head> holds metadata describing the page; <body> holds the content to actually display", "<head> content is there but hidden by a default CSS rule that every browser quietly applies", "The browser randomly picks one of the two every time, so behaviour can change on reload"], ans: 1, why: "<head> holds metadata ABOUT the page (title, charset, stylesheet links, SEO tags) — browsers use these to configure rendering. <body> holds content TO BE DISPLAYED. Browsers need config first (so rendering is right) and content second (so there's something to render).", bloom: "understand" },
    { q: "What does the lang attribute on the <html> tag (for example lang=\"en\") actually do for a page?", opts: ["It picks the page's background colour based on the culture of the chosen language automatically", "It is required for the page to load at all, and without it the browser refuses to display anything", "It translates the whole page into English every time, no matter what the original language was", "It tells browsers, screen readers, and search engines which human language the content is in"], ans: 3, why: "lang tells assistive tech which language to pronounce, helps search engines, and enables features like spellcheck and translation prompts. It doesn't translate or style anything — it announces \"this page is written in X.\" Small attribute, big accessibility win.", bloom: "understand" },
    { q: "A student is writing a new page. Which order of the main skeleton pieces is correct?", opts: ["html wrapping body, body wrapping head — so the head is nested inside the body area", "html twice, once wrapping head and again wrapping body — two separate html blocks in one file and most modern teams have moved to exactly this way of doing things", "doctype first, then html wrapping head and then body, with everything closing in reverse order", "doctype first, then body directly wrapping head without any html element around them at all"], ans: 2, why: "The required order is DOCTYPE → <html> → <head> → <body>. Head comes before body inside <html>. Nesting body inside head (or using two <html> tags) is invalid markup. Follow the shape every time.", bloom: "apply" },
    { q: "A page's <title> says \"Welcome\" but the top of the rendered page shows a heading \"Home.\" Is this a bug?", opts: ["Yes, the page is broken and the browser will eventually refuse to load it after some retries", "Yes, the title and the main heading are required by HTML to match character-for-character on every page", "No — <title> appears in the browser tab and search results; <h1> is the heading on the page itself", "Only on mobile phones, where a special rule forces the tab title and the heading to stay in sync"], ans: 2, why: "<title> lives in <head> and appears in the browser tab and search results. <h1> is the on-page heading. They can differ on purpose — e.g., title tuned for SEO, heading tuned for readers. Different jobs, different text allowed.", bloom: "apply" },
    { q: "You want a page to scale nicely on phones. Which <head> element handles that?", opts: ["A meta viewport element telling the browser to match the device width and start at scale 1", "A link element pointing to a stylesheet file that quietly enables mobile support for the whole page", "A script element that detects phones at load time and rewrites the page's body automatically", "A title element whose text contains the word mobile somewhere so the browser adapts layout"], ans: 0, why: "A <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"> line tells mobile browsers to use the device's real width instead of a zoomed-out desktop width. Without it, phones shrink pages to look \"desktop-ish\" and everything becomes tiny.", bloom: "apply" },
    { q: "A developer writes a heading using the same tag name twice at the start but forgets the slash at the end. The page still renders fine on their laptop. Why is this still a problem?", opts: ["The slash is decorative and most browsers ignore whether it's present, so there's no problem at all", "The page will suddenly stop rendering tomorrow because browsers only forgive mistakes for 24 hours", "Missing slashes only affect printing — the browser will always show it perfectly on the screen itself and most modern teams have moved to exactly this way of doing things", "Browsers auto-correct common errors differently, so behaviour varies across browsers, accessibility tools, and nested elements"], ans: 3, why: "Browsers are forgiving and auto-correct common mistakes, but the outcome varies across browsers, screen readers, and nested elements. \"It works on my machine\" isn't the same as \"it's correct.\" Valid HTML is a contract, not a look.", bloom: "analyze" },
    { q: "A designer calls the DOCTYPE \"optional noise\" because pages render fine without it. Evaluate this view.", opts: ["Correct — just skip the DOCTYPE entirely, it's a legacy line that nobody needs on modern websites", "The DOCTYPE was officially removed from HTML5 and browsers now add it automatically for every page", "Correct — modern browsers quietly insert the DOCTYPE for you, so typing it in the file is duplication and most modern teams have moved to exactly this way of doing things", "Flawed — without DOCTYPE, browsers fall back to \"quirks mode\" and CSS behaves in unpredictable old ways"], ans: 3, why: "Without <!DOCTYPE html> browsers drop into \"quirks mode,\" emulating 1990s behaviour: different box model, odd CSS quirks, inconsistent rendering. One missing line can waste hours debugging layout bugs. Fifteen characters are worth it — not optional.", bloom: "evaluate" },
    { q: "Design the head section of a multilingual blog page that loads fast on phones, shows a nice tab title, and links to an external stylesheet. What should it contain?", opts: ["Only a body tag with all the content jammed inside and no head section above it at all", "A head with lang set on html, UTF-8 charset, a viewport meta, a descriptive title, and a stylesheet link", "A head containing only the title element, with no charset and no viewport, to keep things minimal", "A head stuffed with every possible meta tag ever invented, plus five or six different stylesheet links and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "Good head: <!DOCTYPE html>, <html lang=\"en\">, <meta charset=\"UTF-8\">, <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">, a meaningful <title>, and a <link rel=\"stylesheet\" href=\"styles.css\">. Each line earns its place: standards mode, language, encoding, mobile scaling, tab text, and design.", bloom: "create" },
  ],

  // ─── Topic 3: Tags vs Elements (block vs inline) ───
  3: [
    { q: "Which set of tags are all inline elements that flow within a line of text?", opts: ["div, p, h1 — three of the most common block-level containers used on every web page ever", "section, article, main — the main semantic blocks used to structure the major page regions and most modern teams have moved to exactly this way of doing things", "span, strong, em, and a — small elements that sit inside a line of text without breaking it", "header, footer, nav — semantic blocks that sit at the top and bottom of almost every site"], ans: 2, why: "Inline elements flow inside a line of text without starting a new line. <span>, <strong>, <em>, and <a> all fit. The other sets are block-level elements — they occupy their own horizontal strip by default.", bloom: "remember" },
    { q: "What is the difference between an HTML tag and an HTML element?", opts: ["Tag and element are exactly the same thing — developers just use two different words for one idea", "A tag is the markup (like the opening or closing piece); the element is the whole thing — tags plus content", "Tags are only used in the head section, while elements are only ever used inside the body section", "Elements are written in HTML, while tags are written in CSS and attached to elements at render time and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "A tag is the markup bracket piece (the opening tag or the closing tag). An element is the full unit — opening tag, content, closing tag — taken together. Tags are the brackets; the element is the whole sandwich.", bloom: "remember" },
    { q: "Why do block-level elements start on a new line, while inline elements don't?", opts: ["Browsers pick it randomly per page, so the same element can be block on Monday and inline on Tuesday", "Only newer HTML5 elements start on new lines; everything older than 2010 is always inline by default", "Block elements are structural chunks; inline elements are pieces inside those chunks, so they sit in the flow", "Block elements are physically larger in memory and the browser needs extra space to unpack them each time and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "Block elements represent structural chunks (paragraphs, sections) — they semantically own a \"block\" of the page. Inline elements are pieces WITHIN a chunk (a bold word, a link mid-sentence). Default layout follows semantic meaning.", bloom: "understand" },
    { q: "A paragraph contains a link inside a sentence. What kind of nesting is that, and is it allowed?", opts: ["Block inside inline — never allowed, and the browser will refuse to display the page until it's fixed and most modern teams have moved to exactly this way of doing things", "Block inside block — fine, but only if they are separated by a blank line in the HTML source code", "Inline inside inline — not allowed, and screen readers will announce an error whenever they reach it", "Inline inside block — completely fine, since inline elements are designed to live inside block containers"], ans: 3, why: "A link (<a>) is inline; a paragraph (<p>) is block. Inline-inside-block is the everyday case and completely valid. The reverse — block-inside-inline — is generally wrong and triggers unexpected layouts.", bloom: "understand" },
    { q: "You want to highlight a single word \"crucial\" inside a paragraph without breaking the line. Which element fits?", opts: ["div — the standard generic block container used for grouping bigger chunks of related content together", "section — a semantic block that marks a thematic region of the page with its own heading structure", "span, or a semantic inline tag like strong, em, or mark — something that stays inline with the sentence", "article — a self-contained semantic block meant for a whole post, story, or independent piece of content"], ans: 2, why: "Inside a paragraph you need an inline element. <span> is the generic inline container; <strong>, <em>, or <mark> are semantic options if the highlight carries meaning. Block elements like <div> or <section> would break the line.", bloom: "apply" },
    { q: "You need to group a logo, site title, and navigation bar at the top of every page. Which element is best?", opts: ["A span element, because it visually groups things without adding extra spacing around the group", "A strong element, which marks the group as important and lets screen readers read it with emphasis", "An em element, which emphasises the group's content so it stands out more than the rest of the page", "A header element — a semantic block-level container for introductory content at the top of the page"], ans: 3, why: "Grouping structural content = block-level container. <header> is the semantic winner for top-of-page groups; <div> is a generic fallback. Inline elements like <span>, <em>, <strong> can't structurally group blocks.", bloom: "apply" },
    { q: "A student writes a paragraph tag, then puts a whole section tag inside it. What happens in the browser?", opts: ["It displays correctly and is recommended because section adds extra semantics inside a paragraph", "The browser silently closes the paragraph before the section, so the structure ends up unexpectedly different", "The page refuses to load and shows a big red error banner above the whole body of the document", "Nothing visual changes at all and the code is completely valid according to the HTML specification and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "A <p> can only contain inline content. When a block-level <section> appears inside, the browser auto-closes the <p> just before the <section> to recover. The final structure isn't what you typed, which is confusing later.", bloom: "apply" },
    { q: "A developer wraps an entire article in a single <span> tag. The page still looks fine. What breaks?", opts: ["Nothing at all — span and article behave the same way once CSS styles have been applied to them both", "The layout visually looks fine, but semantics, accessibility, and SEO quietly break because span is inline", "Only inline text inside will display; any images or headings inside the span are silently hidden by browsers", "The browser immediately crashes when it meets the span, because span can't legally wrap multiple elements"], ans: 1, why: "Visually CSS can fake it, but semantically the article is now marked as inline content. Screen readers handle it differently, block-layout CSS can misbehave, and search engines don't recognise it as an article. \"Renders\" isn't the same as \"correct.\"", bloom: "analyze" },
    { q: "Evaluate this practice: \"Use <div> for everything — avoid semantic tags like <header>, <nav>, <main> because they add complexity.\"", opts: ["Flawed — semantic tags give free accessibility and SEO; div-only layouts need aria attributes everywhere to recover", "Correct — div is universal, so using it for every section keeps the codebase simple and easy for new developers and most modern teams have moved to exactly this way of doing things", "Correct — complexity is always bad, and semantic tags are really just divs with extra work layered on top", "Semantic tags don't actually exist in real browsers and mostly get silently converted back into divs anyway"], ans: 0, why: "Semantic tags convey meaning for free to screen readers, search engines, and future maintainers. A div-only layout needs aria-labels everywhere to recover what semantics gave you automatically. Semantic HTML is simpler AND clearer.", bloom: "evaluate" },
    { q: "Design the structural skeleton (elements only, no content) for a news-article page with: site header, main article, related-articles sidebar, site footer.", opts: ["One giant div containing everything, with class names used to distinguish the four separate regions visually", "Only inline elements like span and strong, since they're lightweight and simpler for the browser to process", "A header, a main containing both an article and an aside for related content, and a footer at the bottom", "No structural tags at all — just raw text and images, relying entirely on line breaks for visible separation"], ans: 2, why: "Use semantic block elements: <header>, <main> containing <article> and <aside>, then <footer>. Assistive tech and SEO read the structure directly. A div-only version works visually but loses every free piece of meaning.", bloom: "create" },
  ],

  // ─── Topic 4: Attributes (src, href, alt) ───
  4: [
    { q: "Which statement about HTML attributes is correct?", opts: ["Attributes must always be written inside the closing tag, never in the opening tag of any element", "Attributes appear inside the opening tag as name-equals-value pairs, giving extra info about the element", "Attributes are purely optional and have absolutely no effect on how the browser renders the element and most modern teams have moved to exactly this way of doing things", "Attributes only work in CSS files and the browser ignores any attribute written in a raw HTML file"], ans: 1, why: "Attributes go inside the opening tag as name=\"value\" pairs, separated by spaces. They configure the element — src, href, alt, class, id, and so on. They're functional, not decorative.", bloom: "remember" },
    { q: "On an <img> element, which attribute tells the browser where to find the actual image file?", opts: ["The image attribute, which is the obvious choice because its name literally matches what the tag displays", "The alt attribute, which contains a backup filename in case the main image happens to fail to load properly", "The href attribute, which stores the image's location the same way it does for any normal anchor link", "The src attribute, which holds the path or URL of the image that the browser should download and display"], ans: 3, why: "<img src=\"...\"> points to the image file. href is used for links (<a>), not images. alt is the text alternative, not the file location. Each attribute has a specific job; memorise the common ones.", bloom: "remember" },
    { q: "Why must an id be unique on a page, while class can be repeated across many elements?", opts: ["It's an arbitrary rule that the original inventors of HTML chose at random in the early 1990s", "Old browsers didn't support class at all, so id had to carry the uniqueness rule for historical reasons and most modern teams have moved to exactly this way of doing things", "id is designed for identity (one element); class is designed for grouping (many related elements at once)", "Id and class are actually identical in behaviour — the two names exist only for stylistic preference"], ans: 2, why: "id identifies a specific element — useful for CSS, JavaScript (getElementById), and URL fragments like #section1. Duplicates break those references. class exists to group many elements under shared styles, so repetition is its whole point.", bloom: "understand" },
    { q: "What is the purpose of the alt attribute on an image?", opts: ["It sets the image's file size in kilobytes so the browser can plan how long the download will take", "It is an old attribute that no longer does anything in modern browsers and can safely be left empty always", "It stores the original photographer's name so the browser can show a credit when the user right-clicks it", "It provides a text alternative that screen readers read and that displays when the image fails to load"], ans: 3, why: "alt text is the image's description for screen readers, search engines, and fallback when the image can't load. A descriptive alt is one of the cheapest accessibility wins in all of HTML. Always include it on meaningful images.", bloom: "understand" },
    { q: "You want a link to an external site that opens in a new tab. Which attributes belong on the anchor element?", opts: ["An href attribute for the URL, a target of _blank for a new tab, and rel=\"noopener\" for safety", "A url attribute for the address and a new attribute set to the value tab to tell the browser to open one", "A link attribute for the destination and an open attribute set to new, following older HTML conventions", "A window attribute set to _blank with nothing else — older browsers only need that single attribute to work"], ans: 0, why: "<a href=\"...\" target=\"_blank\" rel=\"noopener\"> is the pattern. href is the destination, target=\"_blank\" opens a new tab, rel=\"noopener\" prevents the new tab from accessing window.opener (a small security best practice).", bloom: "apply" },
    { q: "You're embedding a photo of a school's CEO in a news article. Which set of attributes should you use on the img?", opts: ["Just the src attribute on its own and nothing else, since extra attributes slow the page down slightly", "src, a descriptive alt, width, height, and loading=\"lazy\" to cover accessibility, layout, and performance", "A single file attribute pointing to the image, since src is a legacy attribute from the early web era", "Only width and height attributes, because browsers can figure out the rest of the image info automatically"], ans: 1, why: "Good image: <img src=\"ceo.jpg\" alt=\"Jane Doe, CEO of Example Corp\" width=\"600\" height=\"400\" loading=\"lazy\">. src (where), alt (accessibility), width/height (prevent layout shift), loading=\"lazy\" (performance). A bare img fails accessibility and layout.", bloom: "apply" },
    { q: "You want to style a group of \"primary\" buttons across a site. Which attribute is right for this job?", opts: ["An id attribute named primary on every button — unique names are the proper way to group in HTML", "A class attribute named btn-primary shared by every primary button so CSS can target them all at once", "An href attribute with the word primary, since CSS can read link destinations to apply shared styling", "A title attribute set to primary on every button, because title is the standard way to label groups"], ans: 1, why: "class is for grouping. Give every primary button class=\"btn-primary\", then style .btn-primary in CSS. id is for unique elements — duplicating it on many buttons would be invalid and break JavaScript lookups.", bloom: "apply" },
    { q: "A page uses the same id=\"main\" on three different divs. A JavaScript line using getElementById(\"main\") behaves inconsistently. Why?", opts: ["There's a hidden bug in JavaScript engines that only appears when the letter m is used in an id", "IDs shouldn't exist in modern HTML and browsers are starting to phase them out in favour of classes", "The three divs are valid, but JavaScript is broken in general and shouldn't be used for DOM work anyway and most modern teams have moved to exactly this way of doing things", "Duplicate IDs break uniqueness: getElementById returns the first match, while other APIs may find all three"], ans: 3, why: "getElementById returns the FIRST match only, so two of the three divs become invisible to that call. Other APIs (querySelectorAll(\"#main\")) might pick them all up. The inconsistency comes from violating id's uniqueness rule — rename duplicates to classes.", bloom: "analyze" },
    { q: "A developer argues: \"I prefer inline style attributes because external CSS feels too indirect.\" Evaluate.", opts: ["Correct — inline style is simpler to read and never causes any problems even on much larger sites", "Both inline and external CSS are equally bad because CSS itself is a flawed approach to page styling", "Correct — external CSS is obsolete and all modern sites are moving back to inline style attributes again", "Flawed — inline styles can't be reused, themed, or cached, and overriding them is painful at any scale"], ans: 3, why: "Inline styles can't be reused, are hard to override (high specificity), bloat HTML, hurt caching, and can't be themed. External CSS fixes all of those. Inline is fine for a one-off override, but not as the default approach.", bloom: "evaluate" },
    { q: "Design a consistent attribute convention for a small team's HTML: class naming, id usage, and required attributes. What rules would you adopt?", opts: ["No rules at all, to give every developer full creative freedom on every single element they write", "Kebab-case purpose-based classes, sparing IDs for landmarks, required alt/href/label, with a linter enforcing it", "Random class and id names chosen on the spot, since naming is personal preference and rarely causes issues", "Use only inline style attributes on every element and forbid classes or ids anywhere in the codebase forever and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "Sensible rules: class names kebab-case and purpose-based (btn-primary, nav-item) not appearance-based (red-text); IDs only for landmarks and JS hooks; every <img> has alt, every <a> has href, every input has a <label>; linter enforces. Rules turn drift into consistency.", bloom: "create" },
  ],

  // ─── Topic 5: Comments in HTML ───
  5: [
    { q: "Which is the correct syntax for a comment in HTML?", opts: ["Two forward slashes followed by the comment text on the same line, just like in JavaScript syntax", "A slash-star opening and a star-slash closing, just as CSS block comments are written between them", "An opening bracket, exclamation, two dashes, then the text, and two dashes with a closing bracket", "A hash sign followed by the comment text on the same line, exactly as shell scripts and Python use"], ans: 2, why: "HTML uses <!-- comment --> — angle bracket, exclamation, two dashes, text, two dashes, closing angle. // belongs to JavaScript, /* */ to CSS, # to shells and Python. Each language has its own comment style.", bloom: "remember" },
    { q: "What is the main purpose of comments in HTML?", opts: ["To add hidden text that search engines treat as extra keywords for boosting the page's ranking fast and most modern teams have moved to exactly this way of doing things", "To make parts of the page load faster by telling the browser to skip them during the rendering step", "To encrypt small parts of the page so that only trusted users can read the content inside the tags", "To leave notes for humans reading the source code; comments are ignored by the browser when rendering"], ans: 3, why: "Comments are notes for humans — explaining why something exists, marking sections, or temporarily disabling code. Browsers skip them when rendering. They don't affect SEO ranking, don't encrypt anything, and don't speed up rendering in any meaningful way.", bloom: "remember" },
    { q: "Why are HTML comments still visible in \"View Source\" even though users don't see them on the page?", opts: ["It's a bug in most browsers that the browser vendors have decided is not worth the cost of fixing", "Comments are only visible in Chrome; Safari, Firefox, and Edge all correctly strip them before displaying and most modern teams have moved to exactly this way of doing things", "Comments ship in the source code delivered to the browser — not rendered, but still downloaded and readable", "Comments are encrypted in transit but the browser decrypts them in View Source for debugging purposes"], ans: 2, why: "Comments live in the HTML file that the server sends. Browsers skip rendering them but the source text is there for anyone clicking View Source. \"Hidden\" means not rendered, not \"not downloaded.\" That's why secrets in comments are a bad idea.", bloom: "understand" },
    { q: "Can comments appear anywhere in an HTML file, or are there restrictions?", opts: ["They can appear almost anywhere in the body or head, but not inside the opening tag of another element", "They can only appear right at the very top of the file, before the doctype, and nowhere else in the page", "They can only appear inside the body section, never in head, script, or style sections of the document", "They can appear literally anywhere including in the middle of tag names and attribute values at will"], ans: 0, why: "Comments can sit between elements, inside <head>, inside <body>, etc. — but not inside an opening tag (between attributes) and not inside <script>/<style> as HTML comments (those have their own comment syntax). Good rule: outside tag brackets is usually safe.", bloom: "understand" },
    { q: "You want to temporarily disable 10 lines of HTML without deleting them. What's the fastest way?", opts: ["Cut the 10 lines out and paste them into a separate text file stored somewhere on your computer for later", "Change every tag in those 10 lines to uppercase so the browser no longer recognises and renders them correctly and most modern teams have moved to exactly this way of doing things", "Wrap the 10 lines in a comment — angle bracket exclamation dash dash at the start and dash dash closing at the end", "Delete the 10 lines completely from your editor now and plan to retype them later when you need them back"], ans: 2, why: "Wrap them in <!-- ... -->. The browser ignores the commented section, but the code stays in the file ready to un-comment later. Faster than cut/paste, reversible in seconds, standard practice for debugging.", bloom: "apply" },
    { q: "You're debugging a broken layout and aren't sure which part is causing the problem. How can comments help?", opts: ["Rewrite the whole file from scratch to see if the rewritten version happens to render without the same issue", "Restart the computer completely, since HTML bugs are almost always caused by underlying hardware failures", "Delete the stylesheet link and ignore the visual problem, so you can focus on shipping the rest of the feature", "Comment out large sections and uncomment them one by one, narrowing down which part triggers the problem"], ans: 3, why: "Binary-search with comments: comment out half the file, see if the bug disappears, narrow down from there. Once you've isolated the breaking section, dig in. Way faster than guessing. Comments let you ask \"would removing this fix it?\" without losing code.", bloom: "apply" },
    { q: "You want to mark major sections of a long HTML file so teammates can scan quickly. How would you use comments?", opts: ["Sprinkle random short comments throughout the file to make it feel friendlier to read on first glance", "Use bold visual dividers like equal signs around section names inside comments to mark each major region", "Only add comments at the very end of the file, grouped in one big block that summarises everything above", "Skip comments entirely — file structure should come from indentation, and comments just add more clutter"], ans: 1, why: "Dividers like <!-- ===== HEADER ===== --> or <!-- ===== MAIN ===== --> make big files scannable. Consistent style across the file lets teammates jump to sections by eye. This is one of comments' best uses.", bloom: "apply" },
    { q: "A developer's HTML file has comments like an API_KEY value and a TODO about a security bug on the admin page. What's the risk?", opts: ["Very low risk because comments are private and nobody outside the development team has any way to see them", "There's no risk at all, since only developers using the same editor can read the comments inside the file", "Risk only appears if the comments are spelled wrong, in which case the page might fail to load as expected", "Serious risk — anyone opening View Source sees both the secret key and a clear roadmap of known weaknesses"], ans: 3, why: "Comments are visible via View Source to anyone. API keys in HTML equal immediate credential theft. A TODO about a security bug gives attackers a free roadmap. Move secrets to server-side config and put security TODOs in a private tracker.", bloom: "analyze" },
    { q: "A team debates: \"Should every HTML element have a comment explaining what it does?\" Evaluate.", opts: ["Yes — more comments always mean better code quality, because every reader benefits from more explanation", "Yes, comment every single character and every attribute to give maximum information for future maintainers", "Flawed — comment WHY something exists (non-obvious decisions), not WHAT a visible tag already tells you", "Never comment anything in HTML files; rely completely on self-documenting tag names and meaningful class names"], ans: 2, why: "Comments should explain WHY (non-obvious decisions, trade-offs, TODOs), not WHAT (which the tags already say). A <nav> doesn't need \"this is navigation.\" Comment-everywhere produces noise that hides the notes that actually matter.", bloom: "evaluate" },
    { q: "Design a commenting convention for a team's HTML files: what SHOULD be commented, what shouldn't, and what format?", opts: ["Section dividers, non-obvious business rules, TODOs with owner and date — not obvious tags or any secrets", "Comment every single line of HTML, even the short ones, for maximum redundancy across the whole codebase", "No comments at all; all teams should communicate only through chat and documentation outside the code files", "Random comments wherever anyone feels like it, with no agreed format, so each file reflects its author's taste"], ans: 0, why: "Good convention: comment section dividers, non-obvious business rules, TODOs with owner+date (e.g., TODO(kush, 2026-05): move to CMS), browser-specific workarounds. Don't comment: obvious tag meanings, secrets, private TODOs. A shared format makes files scannable.", bloom: "create" },
  ],

  // ─── Topic 6: Text formatting (strong, em, b, i, mark) ───
  6: [
    { q: "Which pair of tags are semantic — meaning they indicate meaning, not just visual style?", opts: ["The strong and em tags, which mark importance and emphasis and are announced by screen readers accordingly", "The b and i tags, which produce exactly the same bold and italic look but are kept only for legacy reasons", "The u and s tags, which add an underline and a strike-through for presentation without any extra meaning", "The small and big tags, which change text size visually and carry no accessibility information at all"], ans: 0, why: "<strong> means importance and <em> means emphasis — screen readers change intonation to convey them. <b> and <i> produce the same visual bold/italic without semantic meaning. Same pixels, different information: semantic tags convey both.", bloom: "remember" },
    { q: "What does the <mark> tag do?", opts: ["It draws a thick black border around the tagged text and adds a small icon on the right side of the line", "It is an older tag that no longer has any visible effect in modern browsers and is ignored by the renderer", "It marks the text as deleted and displays it with a strike-through line running straight through the middle and most modern teams have moved to exactly this way of doing things", "It highlights text as if with a marker pen, signalling relevance such as a search match or important context"], ans: 3, why: "<mark> highlights text — the default style is a yellow background like a highlighter pen. Semantically it means \"this part is relevant,\" often used for search hits or highlighted context. Screen readers can announce it too.", bloom: "remember" },
    { q: "Why does a screen reader announce <strong> text differently from <b> text, even though both look bold?", opts: ["It's a bug in screen readers that will eventually be fixed when the two tags get treated identically again", "All bold text is read identically; any difference you thought you heard is just random variation in playback", "Screen readers can't read bold text at all, so both tags end up being read the same way with no emphasis", "<strong> carries semantic meaning (\"this is important\"); <b> is purely presentational with no extra meaning"], ans: 3, why: "<strong> encodes importance, so screen readers may raise pitch or add emphasis. <b> is pure presentation and doesn't trigger any extra announcement. HTML encodes both meaning and appearance — use the semantic tag when meaning matters.", bloom: "understand" },
    { q: "When would you use <b> and <i> instead of <strong> and <em>?", opts: ["Always — <strong> and <em> are deprecated and should be avoided in any modern production HTML codebase", "Whenever you want the text bold or italic purely for visual style without conveying importance or emphasis", "Only when you're writing very old-style HTML documents and want the browser to handle them like the 1990s and most modern teams have moved to exactly this way of doing things", "Never — <b> and <i> no longer exist in HTML5 and have been completely replaced by strong and em tags only"], ans: 1, why: "<b> and <i> are for visual offset without meaning — a ship name in italic, a product name in bold. When the emphasis carries meaning (important, stressed), prefer <strong>/<em>. Both sets are valid in HTML5 for their specific roles.", bloom: "understand" },
    { q: "A chemistry page needs to render H₂O with the 2 below the baseline. Which tag handles that?", opts: ["The sup tag, which raises the 2 above the baseline — useful for things like x squared or ordinal endings", "The sub tag, which lowers the 2 below the baseline so formulas like H₂O and CO₂ display in the standard way", "The small tag, which just shrinks the 2 without moving it up or down, so it still sits on the baseline with the letters", "The strong tag, which bolds the 2 and leaves it at normal height, which isn't really the chemistry notation"], ans: 1, why: "<sub> drops text below the baseline — use it for H<sub>2</sub>O, CO<sub>2</sub>, etc. <sup> raises text above the baseline — for x<sup>2</sup>, footnote markers, and ordinals. Two tags, opposite directions.", bloom: "apply" },
    { q: "A revision-tracked document shows \"The meeting is at ~~3pm~~ 4pm.\" Which tags should represent the old and new times?", opts: ["The del tag around 3pm for deleted, and the ins tag around 4pm for inserted — both are revision-aware tags", "The strong tag around both 3pm and 4pm, so the reader notices the change by seeing both times in bold text", "The em tag around 3pm and the u tag around 4pm, using italic for the old and underline for the new one", "No tags are needed — a plain strike-through character in the text is enough to communicate the revision clearly"], ans: 0, why: "<del> marks deleted content (struck through) and <ins> marks inserted content (often underlined). They're the semantic revision tags. Screen readers can announce \"deleted\" or \"inserted,\" which plain styling can't do.", bloom: "apply" },
    { q: "You're writing a blog post about citrus fruits. The Latin name \"Citrus limon\" should be shown in italic as a stylistic convention. Which tag?", opts: ["The em tag, so screen readers add emphasis whenever they read the name out loud in any assistive context", "The i tag, because the italics here are a stylistic convention for species names rather than actual emphasis", "The strong tag, which will make the name bold even though the convention actually calls for italics styling and most modern teams have moved to exactly this way of doing things", "A mark tag, which will highlight the name with a background colour matching the page's primary accent shade"], ans: 1, why: "The italic here is a stylistic convention, not spoken emphasis — so <i> is correct. <em> would tell screen readers to stress it, which isn't what you want. Match the tag to the meaning, not just the look.", bloom: "apply" },
    { q: "A developer uses <u> tags to emphasise headings so they show with an underline. What downstream problem does this create?", opts: ["No problem at all — underline is a perfectly normal and expected way to emphasise any kind of heading on the web", "The u tag doesn't exist in HTML5, so the browser silently ignores it and leaves the heading without any styling at all", "Underlined text looks like a hyperlink by long-standing web convention, so users will try to click the heading", "Headings can't be emphasised by any tag, so the attempt fails entirely no matter which tag the developer chose"], ans: 2, why: "Underline = hyperlink in 30 years of web convention. Users try to click underlined headings, nothing happens, trust drops a bit. Use <strong> or CSS for visual emphasis; reserve underline for actual links. Tag choice interacts with user expectation.", bloom: "analyze" },
    { q: "A designer proposes using <b> and <i> everywhere instead of <strong> and <em> because \"semantic tags are over-engineering.\" Evaluate.", opts: ["Correct — semantics is unnecessary complexity and modern browsers treat all four of these tags as the same anyway", "The b and i tags don't exist in modern HTML at all, so the designer's plan would actually fail on every major browser", "Correct — simpler is always better, and stripping meaning from markup keeps the HTML file size nicely small as well", "Flawed — semantic tags cost zero extra characters and give free accessibility and SEO wins at no real runtime cost"], ans: 3, why: "<strong>/<em> cost exactly the same characters as <b>/<i>, and provide accessibility, SEO, and styling hooks for free. Calling them \"over-engineering\" ignores the downstream value. Use the semantic tag when emphasis carries meaning.", bloom: "evaluate" },
    { q: "Design the formatting tags for a recipe page: title, ingredient list with key items highlighted, quantities in small text, cooking notes emphasised, deleted \"original\" steps shown struck through, inserted \"updated\" steps shown.", opts: ["Use only the p tag for every single part of the recipe, relying on line breaks and spacing for visual differences", "Use strong for absolutely everything on the page — the title, ingredients, quantities, notes, and instructions", "Use h1 for title, ul with li and strong for ingredients, small for quantities, em for notes, del for old steps, ins for new", "Don't use any tags at all and rely on plain text, trusting that readers will infer which parts of the recipe are important and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "One semantic tag per role: <h1> title, <ul><li> ingredients with <strong> on key items, <small> quantities, <em> notes, <del> deleted steps, <ins> inserted steps. Each tag matches the meaning of that piece. The recipe has many content types — give each one its tag.", bloom: "create" },
  ],

  // ─── Topic 7: Tables (table, tr, td, th) ───
  7: [
    { q: "What is the correct nesting order for basic HTML table elements?", opts: ["A tr nested inside a td nested inside a table, where cells wrap rows that then wrap the outer table tag", "A table nested inside a tr nested inside a td, reversing the normal structure used in school textbook examples", "A td nested inside a tr nested inside a table, so cells sit in rows and rows sit in the outer table element", "Any order will work because browsers automatically rearrange table elements into the correct shape on loading"], ans: 2, why: "<table> wraps rows <tr>, and each row wraps cells <td>. Data cells live inside rows; rows live inside the table. Browsers try to auto-repair bad nesting, but relying on that is fragile.", bloom: "remember" },
    { q: "What is the difference between <td> and <th> in a table?", opts: ["td is for data cells and th is for header cells; header cells are bold and announced as headers by screen readers", "td and th are just two different names for the same tag, and developers can use whichever one they personally prefer", "td is used only inside the head of a table and th is used only inside the body, reversing their modern conventions", "th is for tall cells that should span many rows and td is for normal-height cells, which is purely a layout matter"], ans: 0, why: "<td> is a data cell; <th> is a header cell. Browsers bold and centre <th> by default, and screen readers announce \"column header\" or \"row header\" to help users understand tabular data. Correct header markup is an accessibility must.", bloom: "remember" },
    { q: "Why are tables still the correct choice for tabular data, even though they shouldn't be used for page layout?", opts: ["Tables and layout are exactly the same use case, and the difference between them is purely historical nostalgia", "Tables are never the right tool for anything anymore, and CSS Grid has fully replaced every single table on the web", "Tabular data has real row and column relationships that screen readers rely on; visual layout has no such structure", "Layout tables are actually faster to render than CSS grid, but data tables are slower to render on older hardware"], ans: 2, why: "Tabular data has genuine row/column relationships (schedules, prices, comparison charts). Tables encode that for screen readers. Page layout has no such relationships — using tables for layout forces assistive tech to read navigation as \"cell 1 of a 3x3 data table,\" which is nonsense.", bloom: "understand" },
    { q: "What does the <caption> element do inside a table?", opts: ["It adds a hover tooltip that appears when the user's mouse pointer moves across any cell of the table at all", "It changes the table's background colour and font so the table stands out from surrounding paragraphs visually and most modern teams have moved to exactly this way of doing things", "It marks the first row of the table as a special caption row, used instead of a header row with th elements", "It provides a visible title for the table and helps screen readers announce what the table is about before reading"], ans: 3, why: "<caption> is the table's title — it sits just inside <table> and displays above the table by default. Screen readers announce it first, giving users context before the data. Captions are especially helpful on pages with multiple tables.", bloom: "understand" },
    { q: "You want a 3-column table where the top row contains column titles. Which markup is right?", opts: ["A table with a first row of th cells for the headings, followed by rows of td cells for the data below the header", "A table where the first row contains td cells for everything, since th is only used for very large formal tables and most modern teams have moved to exactly this way of doing things", "A table with three separate tr tags and no td or th at all — browsers will fill in the cells from page context", "A table with one big th cell spanning the whole row followed by td cells packed together underneath it tightly"], ans: 0, why: "Headers in the first row: <tr><th>Name</th><th>Age</th><th>City</th></tr>, then data rows: <tr><td>...</td>...</tr>. Browsers and screen readers treat <th> as column headers automatically, linking each data cell to its column title.", bloom: "apply" },
    { q: "You need a cell that spans 2 columns to act as a section title across them. Which attribute is right?", opts: ["A width attribute set to 2 — the number tells the browser how many columns the cell should span across", "A colspan attribute set to 2, which makes the cell stretch horizontally across exactly two columns of the table", "A rowspan attribute set to 2, which makes the cell stretch vertically across two rows instead of sideways", "A merge attribute set to 2, which is the modern HTML5 replacement for the older colspan and rowspan attributes and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "colspan=\"2\" spans horizontally across 2 columns; rowspan=\"2\" spans vertically across 2 rows. width is a size in pixels or percent, and merge isn't an HTML attribute. Use colspan/rowspan for real cell merging.", bloom: "apply" },
    { q: "A school wants a weekly class schedule: rows for days, columns for time slots, and a bold header row. Which structure fits?", opts: ["A big div with line breaks and tabs simulating columns, so the visual look matches a printed timetable closely", "A table with thead containing a row of th cells for the times, and tbody with tr rows where td holds each class", "A series of paragraphs one after another, each one listing the day and its classes separated by commas or dashes", "An unordered list where each li contains the day and classes, styled with CSS Grid to align them into columns"], ans: 1, why: "A schedule is real tabular data: <table> with <thead><tr><th>Time</th>...</tr></thead> and <tbody><tr><td>Mon</td>...</tr></tbody>. Use <th> for headers, <td> for data, and consider a <caption> for context. Tables are made for this.", bloom: "apply" },
    { q: "A page uses tables to arrange the whole layout: header, sidebar, main content. Analyse what breaks on a mobile phone.", opts: ["Nothing breaks at all, since tables have been perfectly responsive ever since the introduction of HTML5 standards", "Only images inside the table break, while text inside the cells continues to reflow normally on small screens", "The fixed column grid can't reflow, so the layout either shrinks illegibly or forces awkward horizontal scrolling", "Tables are always fully responsive, and mobile browsers already rearrange their cells vertically when the screen is narrow"], ans: 2, why: "Tables have a fixed column grid that doesn't reflow naturally. On a narrow phone screen, the table either shrinks text illegibly or forces horizontal scrolling. CSS Grid/Flexbox reflow to any screen size. Table-layout fails exactly because it's a rigid grid.", bloom: "analyze" },
    { q: "A developer argues: \"Tables are obsolete — we have CSS Grid now, so throw them all out.\" Evaluate.", opts: ["Partly right — tables for page layout are obsolete, but tables for tabular data are still absolutely correct to use", "Fully correct — delete every single table on the site and rewrite everything using CSS Grid as a clean replacement", "Fully correct — tables have been officially removed from HTML5 and no browser will render them in the future", "Wrong — tables are still the best choice for page layout, and CSS Grid is mainly useful for tiny decorative elements"], ans: 0, why: "Tables for LAYOUT are obsolete; CSS Grid and Flexbox replaced them. Tables for TABULAR DATA (schedules, prices, comparisons) remain the right tool — semantically and for accessibility. The nuance is use case, not the element itself.", bloom: "evaluate" },
    { q: "Design an accessible HTML table for a class schedule: Day, 9am class, 11am class, 2pm class. Include a caption and proper header markup.", opts: ["Use several paragraphs, one per day, with classes separated by commas — readers can follow the structure on their own", "One enormous cell containing every piece of data, formatted with line breaks to suggest rows and columns visually", "A table with a caption, a thead containing th header cells, and a tbody with tr rows where td cells hold the data", "No table at all — simply list the classes inside a div, relying on whitespace to imply the rows and columns to users"], ans: 2, why: "Good markup: <table><caption>Weekly Class Schedule</caption><thead><tr><th>Day</th><th>9 AM</th><th>11 AM</th><th>2 PM</th></tr></thead><tbody><tr><td>Mon</td>...</tr></tbody></table>. Caption gives context, thead/tbody structure the table, th announces headers, td holds data.", bloom: "create" },
  ],

  // ─── Topic 8: Lists (ul, ol, li, dl) ───
  8: [
    { q: "Which pair of tags represents an ordered list and its items?", opts: ["A ul tag with li tags inside it, which is the standard pattern for most basic lists on any web page today", "An ol tag with li tags inside it, where ol produces the numbered list and li contains each individual list item", "A dl tag with dt tags inside it, which is the modern ordered list shape introduced to replace the older ol element", "A list tag with item tags inside, which is the simpler HTML5 shorthand that replaced the older list structures"], ans: 1, why: "<ol> means ordered (numbered); <ul> means unordered (bulleted); both contain <li> items. <dl> is a description list — different structure (<dt> and <dd>). <list>/<item> aren't HTML elements.", bloom: "remember" },
    { q: "What does a description list (<dl>) contain and what is it used for?", opts: ["It contains dt (description tag) and dd (description data) pairs for listing items with their brief one-line summaries", "It contains li items like every other list type, and the letter d just stands for default list style with no bullets", "It contains only plain text in paragraphs, and browsers automatically add bullets to make it look like a list on screen", "It contains dt (term) and dd (description) pairs for glossaries, FAQs, and any name-value information list needed"], ans: 3, why: "<dl> wraps term-description pairs: <dt> is the term, <dd> is the description. Perfect for glossaries, FAQs (question = term, answer = description), and metadata. Browsers indent <dd> by default to show the pairing visually.", bloom: "remember" },
    { q: "Why use an ordered list for cooking steps but an unordered list for ingredients?", opts: ["Cooking steps are longer, so numbered lists fit them visually better than bulleted lists would on the same page", "They're interchangeable — the HTML spec says ul and ol are equivalent and differ only in their default bullet style", "Steps are a sequence where order matters, while ingredients are a set of things where order doesn't really matter", "Ordered lists save better when printed, so recipes prefer them for the steps that need to survive a printout"], ans: 2, why: "<ol> signals \"order matters\" — step 3 must follow step 2. <ul> signals \"order doesn't matter\" — eggs, milk, flour is the same as flour, eggs, milk. The tag encodes meaning; screen readers use it. CSS can style bullets either way.", bloom: "understand" },
    { q: "Can lists be nested — that is, can a list item contain another list?", opts: ["No, HTML explicitly forbids nesting lists inside one another, and the browser will flag an error immediately", "Only ordered lists can contain other ordered lists; ul cannot hold any other list type inside its li elements", "Yes — an li can contain another ul or ol, which is how outlines and tree-like structures are built in HTML", "Only if you add a special data-nested attribute to every outer li, otherwise browsers render them as flat lists"], ans: 2, why: "Lists nest freely: put a <ul> or <ol> inside an <li>. That's how tables of contents, outlines, and folder trees work. Indentation shows hierarchy in the default style; CSS can adjust. Very common pattern.", bloom: "understand" },
    { q: "You're marking up a FAQ page where each entry has a question and an answer. Which list fits best?", opts: ["An ordered list with numbers for each question, to make it easier for users to reference questions by number and most modern teams have moved to exactly this way of doing things", "An unordered list where questions are bolded and answers follow in the same li on the next line of the item", "A description list with dt for each question and dd for each answer, since this pairs terms with descriptions", "A plain sequence of paragraphs with no list structure at all, relying on font size and spacing for clarity"], ans: 2, why: "FAQ = term + description = <dl><dt>question</dt><dd>answer</dd></dl>. The pair is the structure. <ol>/<ul> don't encode the pairing relationship, and paragraphs give no structure to assistive tech.", bloom: "apply" },
    { q: "You want a numbered list that starts at 5 instead of 1, continuing from a previous page. Which attribute handles that?", opts: ["The begin attribute set to 5 on the ol tag — this is the oldest attribute used for controlling numbering", "The impossible option — HTML lists always restart numbering at 1 and there's no attribute to change this", "The number attribute set to 5 on the ol tag — this is the HTML5 way of overriding the default list numbering", "The start attribute set to 5 on the ol tag — the browser then numbers items 5, 6, 7, and so on from there"], ans: 3, why: "<ol start=\"5\"> begins numbering at 5. There's also type=\"A\" for letters, type=\"I\" for Roman numerals, and reversed to count down. HTML supports these without needing CSS at all.", bloom: "apply" },
    { q: "You want the bullets in an unordered list to be squares instead of discs. Where should you make that change?", opts: ["Set a type=\"square\" attribute on the ul element, which is the standard modern attribute for changing bullets", "Use a CSS rule setting list-style-type to square on the ul — presentation belongs in CSS, not as an attribute", "Replace every li with a custom element and a square symbol typed in front of the item text manually for each", "Change the font family of the list to one that happens to draw square bullets — fonts control all list bullets"], ans: 1, why: "CSS handles presentation: ul { list-style-type: square; }. The old type=\"square\" attribute is deprecated in favour of CSS. Keep content in HTML and styling in CSS — the separation makes maintenance easier.", bloom: "apply" },
    { q: "A developer uses <br> tags to separate list items visually, instead of <ul> and <li>. The page looks like a list but fails accessibility tests. Why?", opts: ["Accessibility tests are wrong and falsely flag br-based lists that are actually perfectly fine for screen reader users", "The br tag is the correct way to build lists in HTML5 and accessibility should accept it as a valid pattern", "Visually it looks like a list, but screen readers hear one long paragraph and can't announce it as a list at all", "Accessibility doesn't matter for most sites, so ignoring the failing tests is a reasonable trade-off for simpler code"], ans: 2, why: "Line breaks LOOK like a list but semantically it's one long paragraph. Screen readers announce \"list of 5 items\" for a real <ul>/<li>, but read the <br> version as continuous text. Users navigating by list landmarks can't find it. Visuals lie; semantics tell the truth.", bloom: "analyze" },
    { q: "A designer argues: \"Use <ul> for everything — ordered lists look the same once CSS is applied, so why bother with <ol>?\" Evaluate.", opts: ["Flawed — visual parity hides wrong semantics; screen readers and SEO still need the correct list type to be used", "Correct — visual appearance is what matters, and using ul for everything keeps the CSS simpler across the site", "Correct — ordered lists are basically a legacy concept and modern sites rarely have any reason to use them", "Correct — HTML tags don't affect anything important, so you can pick any list tag you like on any page you want and most modern teams have moved to exactly this way of doing things"], ans: 0, why: "Visual similarity ignores semantic meaning. <ul> tells screen readers and search engines \"order doesn't matter.\" Using it for steps — where order is critical — is lying in markup. CSS can style either; meaning should still be right. Looks right, meaning wrong, still hurts.", bloom: "evaluate" },
    { q: "Design the list structure for a recipe page: ingredients (order doesn't matter), cooking steps (order is critical), and nutritional definitions (term + explanation).", opts: ["Use p tags for every part of the recipe and add line breaks between items where visual separation is needed", "Use ol tags for all three sections so every part of the recipe is clearly numbered for maximum clarity everywhere", "Use ul for ingredients, ol for steps, and dl with dt and dd for nutritional definitions — one list type per role", "Don't use any list tags at all and write paragraphs throughout, trusting the reader to follow the recipe by eye"], ans: 2, why: "Map meaning to list type: ingredients = <ul><li> (set), steps = <ol><li> (sequence), nutritional definitions = <dl><dt>term</dt><dd>explanation</dd>. Three content types, three list types. Each tag carries meaning screen readers and SEO can use.", bloom: "create" },
  ],

  // ─── Topic 9: Links (a, target, rel) ───
  9: [
    { q: "Which is the correct HTML for a link to example.com?", opts: ["A link element with a url attribute holding the address and Visit as the visible inner text of the tag", "An a element with an href attribute pointing to the full URL, and Visit as the visible text between the tags", "An a element with a link attribute (not href) holding the URL — link is the modern replacement for href", "A url element wrapping the text of the address itself, which browsers interpret as a clickable hyperlink and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "<a href=\"https://example.com\">Visit</a>. Links use <a> (anchor) with an href attribute. <link> exists but is for <head> references (like stylesheets) and isn't clickable. Memorise the <a href=\"...\">text</a> shape.", bloom: "remember" },
    { q: "What does the href attribute do on an anchor tag?", opts: ["It controls whether the link opens in a new tab or the same tab, with values like self, blank, or parent", "It sets the link's visual style (like colour or underline), overriding whatever the CSS file would have provided", "It contains the text that the user actually sees on the page, replacing whatever was written inside the tag itself", "It stores the destination of the link — a URL, a relative path, an anchor fragment, or a tel/mailto scheme"], ans: 3, why: "href holds the destination. The value can be a full URL (https://...), a relative path (/about), an anchor (#section), or a special scheme (mailto:, tel:). Visual styles come from CSS; target controls tab behaviour; text comes from the element's content.", bloom: "remember" },
    { q: "Why do you sometimes need target=\"_blank\" AND rel=\"noopener\" together on a link?", opts: ["They're redundant — pick one of them, since the two attributes do exactly the same thing from slightly different angles", "It's a legacy requirement from old browsers and can be safely skipped on every site built after about 2015 or so", "Without rel=\"noopener\", the new tab can reach back through window.opener and manipulate the original page's URL", "noopener has been deprecated and is automatically applied by every browser whenever target=_blank is used today"], ans: 2, why: "target=\"_blank\" opens a new tab. Without rel=\"noopener\", the new tab can reach the original page via window.opener and redirect it — a phishing vector. noopener breaks that reference for safety. Every new-tab link in production should have both.", bloom: "understand" },
    { q: "What does a relative href like \"about.html\" mean, compared to an absolute href like \"https://site.com/about.html\"?", opts: ["Relative links resolve against the current page's URL, while absolute links include the full protocol and domain themselves", "Relative and absolute links behave identically in every way, and the choice is purely a matter of personal style preference", "Relative links only work on offline files and stop working the moment the page is uploaded to a live web server", "Absolute links are being deprecated by browsers and relative links will be the only supported type within a few years"], ans: 0, why: "Relative URLs resolve against the current page's location. \"about.html\" from /docs/index.html means /docs/about.html. Absolute URLs include protocol and domain, so they work from anywhere. Use relative for internal links and absolute for external ones.", bloom: "understand" },
    { q: "You want a link that jumps to an element with id=\"services\" on the same page. What should the href be?", opts: ["services.html — a normal page link works fine because the browser will scroll to the matching id automatically", "A hash symbol followed by the word services — this tells the browser to jump to the element with that exact id", "page@services — the at symbol is the on-page navigation syntax introduced in the HTML5 specification recently", "services with a colon at the end — colons are the standard way to mark on-page fragment identifiers in links"], ans: 1, why: "href=\"#services\" jumps to the element with id=\"services\" on the current page. The # prefix is specifically for on-page fragment navigation. A plain filename would try to load a new page. Small character, big meaning.", bloom: "apply" },
    { q: "You want a \"Call us\" link on mobile that opens the phone dialer with a pre-filled number. Which href scheme?", opts: ["A tel: scheme followed by the full phone number including country code — mobile browsers register a handler for it", "A call: scheme followed by the number — call is a simpler and more modern replacement for the older tel scheme and most modern teams have moved to exactly this way of doing things", "A phone: scheme followed by the number — phone is the descriptive name used by most modern operating systems", "A dial: scheme followed by the number — dial is the cross-platform standard for opening the dialer on phones"], ans: 0, why: "href=\"tel:+998901234567\" is the standard URI scheme for phone dialing. Mobile browsers and apps register handlers for tel:. call:, phone:, and dial: aren't real schemes. Also note mailto: for email.", bloom: "apply" },
    { q: "You want an email link that opens the user's mail app with a pre-filled subject line. Which href?", opts: ["A mailto: scheme with the email address, followed by ?subject= and the subject text URL-encoded after it", "An email: scheme with the address and a subject attribute appended, which is the newer pattern used in HTML5", "A send: scheme with the address and subject passed as two separate comma-separated values inside the href", "A plain address like name at example dot com — browsers auto-detect the pattern and open the mail app for you"], ans: 0, why: "mailto:name@example.com?subject=Hello%20there opens the user's mail app with fields pre-filled. Use %20 for spaces and URL-encode special characters. email:, send:, and plain-text auto-detection aren't standards.", bloom: "apply" },
    { q: "A site's links all say \"click here\" or \"read more.\" Analyse the accessibility and SEO impact.", opts: ["No real impact — search engines and screen readers both handle these generic link texts without any problem at all and most modern teams have moved to exactly this way of doing things", "Only very slow computers are affected, and most users will still understand the page without any real trouble", "Screen readers often read lists of links, and generic text like \"read more\" carries no information about destinations", "SEO doesn't pay attention to link text anymore, so the wording of links has no effect on search engine rankings"], ans: 2, why: "Screen readers let users jump through lists of links, and \"click here, click here, read more\" conveys nothing about destinations. Search engines also use link text to understand where links point. Descriptive text like \"Read our privacy policy\" helps both audiences.", bloom: "analyze" },
    { q: "A developer argues: \"Every link should open in a new tab so users don't lose my site.\" Evaluate.", opts: ["Correct — always force new tabs, since it guarantees users will remember to return to your site after browsing away", "Correct — users enjoy having many tabs open, and every site should fill their browser to help them feel productive", "Flawed — respect user choice; use same-tab by default, with new tabs only for external or supplementary content", "Never use new tabs under any circumstance, not even for external links, since browsers already handle this well"], ans: 2, why: "The browser already has Back and right-click-new-tab. Forcing new tabs breaks user expectations, fills the tab bar, and doesn't stop people leaving. Convention: same-tab for internal navigation, new-tab only for external links or supplementary content (like docs).", bloom: "evaluate" },
    { q: "Design the link patterns for a university site's homepage: what opens in same tab vs new tab, and what link text for each?", opts: ["All links should open in new tabs with generic \"click here\" text, so users can easily explore many pages at once", "Assign tab behaviour and link text at random for every link, letting each developer follow their personal taste fully", "Same tab for internal navigation, new tab with rel=\"noopener\" for external links, and descriptive text throughout", "Don't include any links at all on the homepage, so users have to use the site's search bar to get anywhere useful"], ans: 2, why: "Pattern: same tab for internal navigation (About, Admissions, Courses) so users stay in flow; new tab with rel=\"noopener\" for external resources (library databases, payment gateways) where leaving would lose state; always descriptive link text. Map behaviour to destination type.", bloom: "create" },
  ],

  // ─── Topic 10: Images (img, alt, width) ───
  10: [
    { q: "Which is the correct way to embed an image with basic accessibility?", opts: ["An img tag with a src attribute pointing to the file and a descriptive alt attribute for accessibility purposes", "An img tag with a file attribute instead of src, since file is the clearer modern name for the same thing", "An image tag with the filename written between the opening and closing tags, just like a paragraph would work", "An img tag with the filename between opening and closing tags — img is a normal element with inner content too and most modern teams have moved to exactly this way of doing things"], ans: 0, why: "<img src=\"photo.jpg\" alt=\"Sunset over the Chatkal mountains\">. <img> is self-closing (no </img>). src is the file location; alt is the accessibility description. Filenames don't go between tags; attributes carry that info.", bloom: "remember" },
    { q: "Which attribute on an img tag sets its displayed width in pixels?", opts: ["The size attribute, which takes a number and applies it equally to both width and height at the same time", "The dimensions attribute, which holds both width and height as a single comma-separated pair in one value", "The w attribute — a newer short-form HTML5 alias for width, introduced to save typing in responsive markup", "The width attribute, which accepts a number (pixels) and sets how wide the image should render on the page"], ans: 3, why: "<img src=\"x.jpg\" width=\"600\" height=\"400\" alt=\"...\">. width and height attributes (in pixels) tell the browser to reserve space, preventing layout shift when the image finally loads. CSS can also set sizes, but width/height attributes help with initial layout.", bloom: "remember" },
    { q: "Why does an empty alt=\"\" differ from a completely missing alt attribute?", opts: ["They're identical in every way — browsers and screen readers treat both situations as the same case throughout", "Empty alt marks the image as decorative (screen readers skip it); missing alt often reads the filename aloud", "Empty alt is deprecated and no longer valid, so it should always be replaced with a full description on every image", "Missing alt makes the image invisible on the page, while empty alt shows the image but still reads the filename"], ans: 1, why: "alt=\"\" explicitly signals \"this image is decorative, skip it\" — screen readers silently pass by. Missing alt makes many screen readers announce the filename (\"DSC_0342.jpg\"), which is useless. Three cases: descriptive alt, empty alt, missing alt — each means something different.", bloom: "understand" },
    { q: "What happens if an image's src points to a file that doesn't exist or fails to load?", opts: ["The browser redraws the entire page from scratch every few seconds hoping the image eventually arrives and loads", "The browser shows a broken-image icon, and if alt is set, the alt text appears as a fallback in that space", "The browser silently hides the image and also removes all elements near it to avoid any awkward empty gaps", "The browser crashes the whole tab instantly, forcing the user to reload the page to see any of the content at all"], ans: 1, why: "Failed images show a broken-image icon (or just empty space). If alt is set, many browsers display it in place. This is one of the reasons alt matters even for sighted users — slow connections, bad URLs, and blocked images are common.", bloom: "understand" },
    { q: "You want a logo that, when clicked, takes the user back to the homepage. Which markup is right?", opts: ["An a element with href pointing to the homepage wrapped around an img element with a descriptive alt text", "An img element with an onclick attribute set to home, which is a built-in shortcut recognised by all browsers", "A link element wrapping the img — link is the correct tag to make any element clickable in modern HTML", "An img element with an href attribute pointing directly to the homepage — img supports href for convenience"], ans: 0, why: "<a href=\"/\"><img src=\"logo.png\" alt=\"Company Name — home\"></a>. Wrap the <img> in an <a>. The <img> itself doesn't take href. Accessible alt text explains the link destination. Logo-as-home-link is a universal web pattern.", bloom: "apply" },
    { q: "You're embedding a photo of a chart that shows sales doubling over a year. What should the alt text say?", opts: ["Just the word chart, because short alt text is faster for screen readers to read and keeps the markup lightweight", "A description of the chart's data and trend, such as \"Bar chart: Q1 $50K rising to Q4 $100K — a 2× increase\"", "An empty alt value, since charts are decorative and shouldn't add extra audio noise for screen reader users at all", "Just the word photo, since the image is a picture of a chart rather than the chart rendered directly as SVG data"], ans: 1, why: "Describe the information the image conveys, not just that an image exists. For a chart, spell out the trend: \"Bar chart showing quarterly sales rising from $50K in Q1 to $100K in Q4 — a 2× increase.\" Non-sighted users deserve the same insight as sighted users.", bloom: "apply" },
    { q: "A page has a small decorative border image repeated along the top of every section. What should the alt be?", opts: ["A detailed sentence describing the border's colour, shape, and pixel pattern for completeness on every instance", "An empty alt so screen readers skip it — decorative images shouldn't add noise to the audio reading experience", "The filename of the image file itself, so screen readers have something to say and can help users debug issues", "The word decoration as the alt, since that accurately tells the user what kind of image they're hearing about"], ans: 1, why: "Decorative images should have alt=\"\" so screen readers silently skip them. Announcing a border 10 times down the page would be noise. Descriptive alt is for meaningful images; empty alt is for decoration. Two different tools, two situations.", bloom: "apply" },
    { q: "A site has 40 images and they all use alt=\"image\". Analyse the accessibility and SEO cost.", opts: ["It's acceptable — at least there is alt text on every image, which is what most accessibility checkers look for first", "It's actually an SEO win because the repeated word image makes the page rank higher for image-related queries", "A perfect setup — uniform alt text is tidy, predictable, and easier for maintainers to keep consistent across the site", "Almost as bad as missing alt — screen readers say \"image, image, image\" and search engines learn nothing useful"], ans: 3, why: "Screen readers announce \"image, image, image\" 40 times. Search engines can't index image content. The presence of alt text gets mistaken for quality, but generic alt is almost as harmful as missing alt. Descriptive alt is the goal; checking a box isn't enough.", bloom: "analyze" },
    { q: "A photographer argues: \"I don't need alt text — visually impaired users won't visit a photography site anyway.\" Evaluate.", opts: ["Correct — if the content is visual, skipping alt text is reasonable and saves typing time on every page of the site", "Flawed — low-vision users do visit photo sites, alt helps SEO, fallbacks, and is often required by accessibility laws", "Correct — depends on the audience, and most photography sites can safely leave alt off because of their user base", "Only required for some kinds of sites; photography specifically is exempted from accessibility rules in most countries"], ans: 1, why: "The argument fails on every axis: (1) low-vision users DO visit photography sites; (2) alt helps images appear in search; (3) alt shows when images fail (slow network); (4) accessibility laws require it in many regions. Alt has no downside — always include it.", bloom: "evaluate" },
    { q: "Design the image markup for a responsive product card: a main product photo, two supporting thumbnails, and a clickable zoom icon. Include accessibility and performance attributes.", opts: ["Descriptive alt on content images, empty alt plus aria-label on the icon, width and height set, and lazy loading", "A single plain img tag with no attributes other than src, since extra attributes slow the page down unnecessarily", "Several img tags with no alt attribute anywhere, relying entirely on the product description paragraph below instead", "No images at all on the product card — use only text so the page loads faster and avoids accessibility complexity"], ans: 0, why: "Content images get descriptive alt (\"Red leather backpack, front view\"), width and height attributes (to avoid layout shift), and loading=\"lazy\" (for performance). Icons inside buttons get alt=\"\" plus an aria-label on the button. Right attribute for right role.", bloom: "create" },
  ],

  // ─── Topic 11: Semantic HTML (main, section, article, header, footer) ───
  11: [
    { q: "Which element is meant for the main content area of a page and should be used only once?", opts: ["The div element — a generic container that can be reused anywhere, including for the main page region", "The main element — a semantic container specifically for the page's dominant content, used exactly once", "The section element — a thematic grouping that can appear many times on a single page without any issues", "The article element — a self-contained piece of content that typically appears many times inside a main region"], ans: 1, why: "<main> is for the page's dominant content and should appear exactly once. <section> groups thematic content (can repeat). <article> is self-contained content (can repeat). <div> is generic with no semantic meaning at all.", bloom: "remember" },
    { q: "What is the purpose of the <nav> element?", opts: ["It adds a coloured navigation bar to the top of the page with home, about, and contact links filled in by default", "It is just a visual styling tag that underlines every link inside it and centres the list of links horizontally", "It is a newer replacement for the div element, used whenever a page needs a simple generic container for grouping", "It marks a section of the page that contains major navigation links, helping screen readers jump to the menu fast"], ans: 3, why: "<nav> marks a major navigation region — typically the main menu or an in-page table of contents. Screen readers let users jump straight to it. It doesn't style anything by itself — CSS still handles the look. Semantics first, style second.", bloom: "remember" },
    { q: "Why does a page typically have exactly one <h1>, instead of several?", opts: ["It's an arbitrary rule with no real reason; modern browsers simply prefer single h1 tags for performance reasons", "The h1 tag has been deprecated and most sites now use h2 instead, even for the page's main title or heading", "h1 represents the page's main topic; multiple h1s dilute the signal for screen readers and search engines alike", "Multiple h1 tags crash the browser on mobile phones, so developers avoid them to keep the page reliably loading"], ans: 2, why: "<h1> represents the page's main topic. Multiple h1s dilute the signal — which one is the real topic? Sub-sections use h2, sub-points use h3, and so on. Search engines use h1 as a strong ranking hint; keep it singular and meaningful.", bloom: "understand" },
    { q: "What's the difference between <section> and <article>?", opts: ["They are exactly the same element and browsers treat them identically; the two names exist only for stylistic variety", "<section> is a thematic grouping within a page; <article> is self-contained content that could stand on its own", "<section> is used only inside the head area, while <article> is used only inside the body of an HTML document", "<article> is the legacy tag from older HTML; <section> is its modern HTML5 replacement and should be preferred"], ans: 1, why: "<section> groups related content thematically (e.g., a page's \"About\" area). <article> is self-contained and could be distributed on its own (a blog post, a news item, a forum post). An article can live inside main; a section can live inside or outside an article.", bloom: "understand" },
    { q: "You're building a news-article page. Which semantic element should wrap the article body itself?", opts: ["A div element with a class name like \"article\", which works visually when styled with the right CSS rules", "A section element, which groups the article thematically inside the main content area of the page layout", "An article element, specifically made for self-contained content such as news posts, blog posts, and forum items", "A main element by itself, since main is the natural container for the most important region on the whole page and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "<article> is specifically for self-contained content like a news article, blog post, or forum post. It goes inside <main>, which can hold one or more articles. <section> is for thematic groups; <div> is generic. Match the tag to the meaning.", bloom: "apply" },
    { q: "Apply heading hierarchy to a blog post on \"Remote Work\" with sub-topics \"Benefits\" and \"Challenges.\" Which levels fit?", opts: ["h1 for every heading on the page so they all look the same size and carry equal importance throughout the post", "Random heading levels chosen by visual preference, since heading tags mostly affect text size and little else", "h1 for the main topic, h2 for each sub-topic, and h3 for any sub-points inside those sub-topics as they appear", "Skip levels — h1 for the title, then h3 for sub-topics, and h5 for sub-points, making the outline more dramatic"], ans: 2, why: "h1 = Remote Work. h2 = Benefits. h2 = Challenges. Any sub-points nested inside use h3. Same-level siblings share a heading level, nested levels go one deeper. Skipping levels (h1 → h3) breaks the outline for screen readers.", bloom: "apply" },
    { q: "You want to add a site-wide footer with copyright and contact info. Which element should you use?", opts: ["A div with a class of footer, which looks the same in the browser and is simpler for developers to remember", "The footer element — a semantic block for introductory or closing content at the bottom of the page or a section", "A section element with a heading of Footer, so the browser understands its role through the heading text alone", "A plain paragraph element at the bottom of the body, since footers are just text after all the main content ends"], ans: 1, why: "<footer> is the semantic element for closing content — site-wide copyright, contact info, secondary navigation. Screen readers treat it as a landmark. A <div> with a class works visually but provides no landmark role to assistive tech.", bloom: "apply" },
    { q: "A page uses <div class=\"nav\">, <div class=\"main\">, and <div class=\"footer\"> instead of <nav>, <main>, and <footer>. Analyse what's lost.", opts: ["Nothing is lost — CSS classes perform exactly the same role as semantic tags in every situation on every browser", "Only the default colours are lost; everything else about the page's behaviour and structure stays the same always", "CSS breaks because browsers don't know how to style unknown classes, so the page looks completely unstyled now", "Landmarks for screen readers and SEO are lost; to assistive tech the page becomes one big undifferentiated div"], ans: 3, why: "Screen readers rely on landmarks (nav, main, footer) to let users jump to navigation, main content, or footer. Divs with classes provide no landmarks — every page becomes \"one big div\" to assistive tech. SEO also suffers because crawlers can't identify page regions. Visual result identical, invisible result a disaster.", bloom: "analyze" },
    { q: "A team debates: \"Validate HTML on every commit\" versus \"Ship it if it renders.\" Evaluate.", opts: ["If it renders in Chrome, it's fine — every other browser, screen reader, and tool will also render it identically", "Don't validate because it's slow and the warnings it prints are mostly nitpicks that no real user is ever affected by", "Validate — rendering is the lowest bar, and validation catches edge-case errors that break screen readers and older browsers", "Validate only once a year during a scheduled audit, since validation errors rarely cause user-visible problems in practice and most modern teams have moved to exactly this way of doing things"], ans: 2, why: "Rendering is the lowest bar — browsers hide many real errors (unclosed tags, wrong nesting, missing labels) that break in edge cases: older browsers, screen readers, print, scraping, mobile. Validation catches them cheaply; debugging after deploy is expensive. \"Renders\" hides problems, not fixes them.", bloom: "evaluate" },
    { q: "Design the complete semantic skeleton for a personal portfolio page: name as title, 3-link navigation, about section, projects list, contact footer.", opts: ["Everything inside a single large div element, relying on CSS classes and careful spacing for visual structure alone and most modern teams have moved to exactly this way of doing things", "No structural tags at all — use plain paragraphs and line breaks to separate the parts of the page from each other", "A semantic skeleton using header with h1 and nav, main with sections for about and projects, and a footer for contact", "One giant div wrapping the entire body content, with all the tags inside also being plain divs for consistency"], ans: 2, why: "Skeleton: <header> containing <h1> and <nav>, <main> containing <section id=\"about\"> and <section id=\"projects\">, then <footer> with contact info. Each element tells screen readers and SEO what the region is for — free meaning at no extra cost.", bloom: "create" },
  ],
};
